import React from "react";

const content = [
  "Phishing = Fishing 🎣",
  "Phishing adalah seperti memancing, tetapi penipu menyamar sebagai institusi terpercaya untuk 'memancing' informasi sensitif dari korbannya.",
  "Penipu membuat email atau website palsu, mengirimkan link atau formulir yang meminta informasi pribadi seperti password, nomor kartu kredit, atau data sensitif lainnya."
];

const steps = [
  "Penyerang membuat email atau website palsu yang terlihat resmi.",
  "Menyamar sebagai institusi terpercaya, seperti bank, e-commerce, atau layanan pemerintah.",
  "Mengirimkan pesan mendesak untuk membuat korban cepat percaya dan bertindak.",
  "Korban memasukkan informasi pribadi mereka, yang kemudian dicuri oleh penyerang."
];

export default function Slide1Title({ onNext }) {
  return (
    <div className="w-full max-w-3xl flex flex-col md:flex-row items-center justify-between bg-gradient-to-r from-[#FFDDC1] to-[#FF7F00] rounded-2xl pt-4 pb-8 px-4 md:pt-6 md:pb-10 md:px-10 shadow-xl mt-2 min-h-[420px]">
      {/* Left: Text */}
      <div className="flex-1 pr-0 md:pr-8">
        <h1 className="text-[32px] md:text-[36px] font-extrabold text-[#FF7F00] text-center mb-4 font-montserrat tracking-tight leading-tight">Apa Itu Phishing?</h1>
        <div className="text-[18px] md:text-[20px] text-[#333] italic text-center mb-7 font-poppins font-medium">Teknik penipuan digital yang menyamar sebagai entitas terpercaya untuk mencuri informasi sensitif.</div>
        <ul className="text-[17px] md:text-[18px] text-[#333] font-poppins leading-relaxed space-y-2 mb-5 list-disc list-inside">
          {content.map((item, idx) => (
            <li key={idx} className={idx === 0 ? "font-bold text-lg" : "font-medium"}>{item}</li>
          ))}
        </ul>
        <div className="font-bold text-[#333] mt-2 mb-1 font-poppins">Cara Kerja Phishing:</div>
        <ol className="text-[17px] md:text-[18px] text-[#333] font-poppins leading-relaxed space-y-1 mb-6 list-decimal list-inside pl-4">
          {steps.map((item, idx) => (
            <li key={idx} className="font-medium">{item}</li>
          ))}
        </ol>
        <div className="w-full flex justify-center">
          <div className="bg-white px-6 py-3 rounded-2xl text-center text-[#FF7F00] font-bold text-[16px] shadow mt-2 max-w-xl font-poppins">
            "Ingat: Tidak ada bank atau institusi resmi yang akan meminta password melalui email!"
          </div>
        </div>
        <div className="flex justify-center mt-6">
          <button onClick={onNext} className="bg-[#FF7F00] text-white px-8 py-2 rounded-lg font-bold text-lg shadow hover:bg-orange-600 transition font-poppins">Next</button>
        </div>
      </div>
      {/* Right: Visual */}
      <div className="flex-1 flex justify-center md:justify-start mt-8 md:mt-0 pl-0 md:pl-4">
        <img
          src="https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=400&q=80"
          alt="Orang Memancing"
          className="w-full max-w-xs md:max-w-sm rounded-xl shadow-lg object-cover"
          style={{ borderRadius: '10px' }}
        />
      </div>
    </div>
  );
}
